local a=workspace:WaitForChild('REACTOR_MESH_ASSEMBLY');local st=a:WaitForChild('STATIC');local mov=a:WaitForChild('MOVING');local r={models={},bays={},assets={},counts={emitter=0,piston=0,hatch=0,bay=0,spool=0,empty=0},generatedFlags=a:GetAttributes(),oldModels={}}
for _,name in ipairs({'REACTOR_CORE_MANYETIK_01','REACTOR_REAR_BULKHEAD_REV05_TURBINE_PORT','REACTOR_CROWN_AND_DECK_01','REACTOR_SIDE_DIAG_OPEN_AND_FRONT_SEAL_03','REACTOR_COOLANT_PIPING_RING_01','PISTON_REAR_SERVICE_BAYS_01','REACTOR_FOREBAY_CONTAINMENT_HALL_01','REACTOR_REAR_TURBINE_PLENUM_01','DAMAGE_PIPE_RUPTURE_KIT_01'}) do local x=st:FindFirstChild(name);r.models[name]=x~=nil end
for _,m in ipairs(mov:GetChildren()) do if m.Name:find('REACTOR_EMITTER_REV03_',1,true)==1 then r.counts.emitter+=1 elseif m.Name:find('REACTOR_PISTON_GUIDE_01_',1,true)==1 then r.counts.piston+=1 elseif m.Name:find('REACTOR_WALL_HATCH_THROUGH_01_',1,true)==1 or m.Name:find('REACTOR_RADIAL_HATCH_',1,true)==1 then r.counts.hatch+=1 end end
local bay=st:FindFirstChild('PISTON_REAR_SERVICE_BAYS_01');for _,m in ipairs(bay:GetChildren()) do if m:IsA('Model') and m:GetAttribute('BayCode') then r.counts.bay+=1;r.bays[m.Name]=m:GetAttribute('BayCode') end end
local pipe=st:FindFirstChild('REACTOR_COOLANT_PIPING_RING_01');for _,m in ipairs(pipe:GetChildren()) do if m:IsA('Model') and m:GetAttribute('Faz3RuptureSpool') then r.counts.spool+=1 end end
for _,x in ipairs({'REACTOR_REAR_BULKHEAD_IRON_REV04','REACTOR_SIDE_WALLS_OCTAGONAL_IRON_REV02','REACTOR_REAR_SERVICE_GRILLES_01'}) do local m=st:FindFirstChild(x);if m then local n,vis=0,0;for _,p in ipairs(m:GetDescendants()) do if p:IsA('MeshPart') then n+=1;if p.Transparency<.95 then vis+=1 end end end;r.oldModels[x]={all=n,visible=vis} end end
for _,p in ipairs(a:GetDescendants()) do if p:IsA('MeshPart') and p.MeshId=='' and p.MeshContent.SourceType==Enum.ContentSourceType.None then r.counts.empty+=1 end end
return game:GetService('HttpService'):JSONEncode(r)
